    /**
     * @brief Direct unleased raw pointer query.
     * @warning NOT thread-safe against concurrent service restarts or proxy replacements.
     * Intended primarily for single-threaded test bench mock wiring or inspection.
     * In concurrent application code, always use acquire_alertconsumer_proxy() which returns a safe RAII ProxyLease.
     */
    fan_out_alert::proxy::FanOutAlertBroadcastProxy* get_alertconsumer_proxy() const noexcept { return alertconsumer_slot_.get(); }
    bool is_alertconsumer_ready() const noexcept { 
        return alertconsumer_open_.load(std::memory_order_acquire) && alertconsumer_slot_.is_available(); 
    }
    reaktar::ProxyLease<fan_out_alert::proxy::FanOutAlertBroadcastProxy> acquire_alertconsumer_proxy() { return alertconsumer_slot_.acquire("alertconsumer"); }
    std::optional<typename fan_out_alert::proxy::FanOutAlertBroadcastProxy::HandleType> get_alertconsumer_handle() const noexcept { 
        return alertconsumer_slot_.get_handle(); 
    }
    fan_out_alert::proxy::FanOutAlertBroadcastProxy* get_fan_out_alert_broadcast_proxy() const noexcept { return get_alertconsumer_proxy(); }
    bool is_fan_out_alert_broadcast_ready() const noexcept { return is_alertconsumer_ready(); }
    reaktar::ProxyLease<fan_out_alert::proxy::FanOutAlertBroadcastProxy> acquire_fan_out_alert_broadcast_proxy() { return acquire_alertconsumer_proxy(); }
    std::optional<typename fan_out_alert::proxy::FanOutAlertBroadcastProxy::HandleType> get_fan_out_alert_broadcast_handle() const noexcept { return get_alertconsumer_handle(); }
    /**
     * @brief Direct unleased raw pointer query.
     * @warning NOT thread-safe against concurrent service restarts or proxy replacements.
     * Intended primarily for single-threaded test bench mock wiring or inspection.
     * In concurrent application code, always use acquire_supervisorrequired_proxy() which returns a safe RAII ProxyLease.
     */
    vehicle_supervisor::proxy::VehicleSupervisorProxy* get_supervisorrequired_proxy() const noexcept { return supervisorrequired_slot_.get(); }
    bool is_supervisorrequired_ready() const noexcept { 
        return supervisorrequired_open_.load(std::memory_order_acquire) && supervisorrequired_slot_.is_available(); 
    }
